<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Sorting Visualizer</title>
    <style>
        body {
            background-color: #1e1e1e;
            color: white;
            font-family: sans-serif;
            display: flex;
            flex-direction: column;
            align-items: center;
            padding-top: 20px;
        }
        #bars {
            display: flex;
            margin-top: 20px;
            overflow-x: hidden;
            width: 90vw;
        }
        .bar {
            width: 5px;
            background-color: #4CAF50;
            margin-right: 1px;
        }
        button {
            margin: 5px;
            padding: 10px 20px;
            font-size: 16px;
        }
    </style>
</head>
<body>
    <div id="bars"></div>
    <div>
        <button id="sort">Sort</button>
        <button id="shuffle">Shuffle</button>
        <button id="reset">Reset</button>
    </div>

    <script>
        const arrayContainer = document.getElementById('bars');
        let arrayLength = 30;
        let maxVal = 60;

        function generateRandomArray(length, min, max) {
            return Array.from({length}, () => Math.floor(Math.random() * (max - min + 1)) + min);
        }

        window.viz = {
            _array: [],
            _originalArray: [],
            _k: 0,
            _currentIndex: 1,
            _minIndex: 0,
            _phase: 'finding_min',
            array() {
                return this._array.slice();
            },
            setArray(a) {
                this._array = a.slice();
                this.redrawBars();
                this.resetSortState();
            },
            resetSortState() {
                this._k = 0;
                this._currentIndex = 1;
                this._minIndex = 0;
                this._phase = 'finding_min';
            },
            sorted() {
                for (let i=0; i < this._array.length - 1; i++) {
                    if (this._array[i] > this._array[i+1]) return false;
                }
                return true;
            },
            sortStep() {
                if (this.sorted()) {
                    return true;
                }

                switch(this._phase) {
                    case 'finding_min':
                        if (this._currentIndex < this._array.length) {
                            if (this._array[this._currentIndex] < this._array[this._minIndex]) {
                                this._minIndex = this._currentIndex;
                            }
                            this._currentIndex += 1;
                        }
                        if (this._currentIndex === this._array.length) {
                            this._phase = 'swapping';
                        }
                        return false;

                    case 'swapping':
                        if (this._k !== this._minIndex) {
                            [this._array[this._k], this._array[this._minIndex]] = [this._array[this._minIndex], this._array[this._k]];
                            this.redrawBars();
                        }
                        this._k += 1;
                        if (this._k < this._array.length - 1) {
                            this._phase = 'finding_min';
                            this._currentIndex = this._k + 1;
                            this._minIndex = this._k;
                        } else {
                            return true;
                        }
                        return false;

                    default:
                        return false;
                }
            },
            redrawBars() {
                arrayContainer.innerHTML = '';
                this._array.forEach(val => {
                    const bar = document.createElement('div');
                    bar.className = 'bar';
                    bar.style.height = `${val * 3}px`;
                    arrayContainer.appendChild(bar);
                });
            }
        };

        const initialArray = generateRandomArray(arrayLength, 1, maxVal);
        window.viz.setArray(initialArray);
        window.viz._originalArray = [...initialArray];

        document.getElementById('shuffle').addEventListener('click', () => {
            const newArray = generateRandomArray(arrayLength, 1, maxVal);
            window.viz.setArray(newArray);
            window.viz._originalArray = [...newArray];
        });

        document.getElementById('reset').addEventListener('click', () => {
            if (window.viz._originalArray.length > 0) {
                window.viz.setArray(window.viz._originalArray.slice());
            } else {
                const resetArray = generateRandomArray(arrayLength, 1, maxVal);
                window.viz.setArray(resetArray);
                window.viz._originalArray = [...resetArray];
            }
        });

        document.getElementById('sort').addEventListener('click', () => {
            let intervalId;
            function animateSort() {
                if (window.viz.sortStep()) {
                    clearInterval(intervalId);
                }
            }
            intervalId = setInterval(animateSort, 10);
        });
    </script>
</body>
</html>
